-- ============================================================================
-- Weeks 1–4 authoring specs and assessment specs (generated)
-- Edit the JSON under content/curriculum, then run:
--   node supabase-b1-b2/scripts/build-details-seed.mjs
-- ============================================================================

create table if not exists public.syllabus_week_details (
  week_number int primary key references public.syllabus_weeks(week_number) on delete cascade,
  payload jsonb not null
);

create table if not exists public.syllabus_assessments (
  code text primary key,
  title text not null,
  payload jsonb not null
);

create table if not exists public.syllabus_vocab_items (
  id text primary key,
  week_number int not null references public.syllabus_weeks(week_number) on delete cascade,
  group_kind text not null check (group_kind in ('core', 'collocation', 'family', 'optional', 'linker')),
  target text not null,
  cefr text,
  use_role text,
  example text not null,
  card text not null,
  sort_order int not null
);

create table if not exists public.syllabus_checkpoint_items (
  id text primary key,
  week_number int not null references public.syllabus_weeks(week_number) on delete cascade,
  reserve boolean not null default false,
  target text not null,
  prompt text not null,
  options jsonb not null default '[]'::jsonb,
  key text not null,
  reason text not null,
  sort_order int not null
);

alter table public.syllabus_week_details enable row level security;
drop policy if exists "syllabus_week_details_public_read" on public.syllabus_week_details;
create policy "syllabus_week_details_public_read" on public.syllabus_week_details for select to anon, authenticated using (true);
grant select on public.syllabus_week_details to anon, authenticated;
alter table public.syllabus_assessments enable row level security;
drop policy if exists "syllabus_assessments_public_read" on public.syllabus_assessments;
create policy "syllabus_assessments_public_read" on public.syllabus_assessments for select to anon, authenticated using (true);
grant select on public.syllabus_assessments to anon, authenticated;
alter table public.syllabus_vocab_items enable row level security;
drop policy if exists "syllabus_vocab_items_public_read" on public.syllabus_vocab_items;
create policy "syllabus_vocab_items_public_read" on public.syllabus_vocab_items for select to anon, authenticated using (true);
grant select on public.syllabus_vocab_items to anon, authenticated;
alter table public.syllabus_checkpoint_items enable row level security;
drop policy if exists "syllabus_checkpoint_items_public_read" on public.syllabus_checkpoint_items;
create policy "syllabus_checkpoint_items_public_read" on public.syllabus_checkpoint_items for select to anon, authenticated using (true);
grant select on public.syllabus_checkpoint_items to anon, authenticated;

insert into public.syllabus_week_details (week_number, payload)
select (week.value->>'number')::int, week.value
from jsonb_array_elements('{"version":"2026-11-21","sources":["Revised grammar plan — Weeks 1–4, syllabus aligned (21 Nov 2026)","Vocabulary review — Weeks 1–4, syllabus aligned (21 Nov 2026)","Course syllabus (21 Nov 2026)"],"pilotRules":{"grammarTask":{"minutes":20,"autoMarkedItems":25,"breakdown":[{"type":"meaning checks","count":3},{"type":"choose","count":6},{"type":"complete","count":5},{"type":"fix","count":3},{"type":"rewrite","count":3},{"type":"light items","count":3},{"type":"review items","count":2}],"personalSentences":2,"extraItemsBelow60":3,"skipRewriteAt90Plus":true,"order":"notice forms (2 min), meaning checks (2), choose (3), complete (3), fix (2), rewrite (2), light (2), own sentences with AI feedback (3), review (1)"},"speaking":"Record 60–90 seconds. Hide the model before the first take. One specific AI correction, then record again straight away.","writing":"30 minutes, 120–150 words, instant AI feedback and revise-and-retry. A few days later a new speaking prompt without the phrase bank.","conversation":"15 minutes recommended; 3–4 turns with the AI partner on the week''s theme, grammar and featured words. Feedback after the exchange, then one turn retried.","extensiveInput":"About 60 minutes a week of graded B1 listening or reading with transcripts or captions, tagged to the week''s theme; 40 minutes minimum; up to 5 personal words.","progression":"No fixed days or deadlines. The next week opens when speaking, writing and either listening or reading are done.","level":"Adults and older teenagers (16+) at secure B1. Adult contexts: work, flat-sharing, plans and travel. Judge control and clarity, not the number of forms used.","grammarClinic":"Only syllabus B1 basics: present simple and continuous, articles, quantifiers, prepositions, subject–verb agreement and verb forms. Every Light point is taught in its own week, not moved to the clinic."},"conversationRules":{"levelAndTurns":"The partner speaks at B1 in one- or two-sentence turns and asks one follow-up per turn. Ends after 3–4 learner turns, or earlier on request.","errors":"No interruption or mid-conversation corrections; natural recasts only, e.g. ''Oh, you''ve lived there since May?''","feedback":"After the exchange: up to three corrections prioritising the week''s grammar, one featured word used well or one that would have fitted, then one turn retried.","labelledAsAi":"The partner and its feedback are always labelled as AI; learners can dispute feedback with ''I think this is right''.","accent":"Feedback covers grammar, vocabulary and clarity. A Spanish or regional accent is never an error; misrecognised words are not grammar mistakes.","safety":"Stays on the week''s theme, declines romantic, sexual, harmful or personal-data topics, never asks for an address or phone number, suitable for ages 16–17, report button on every exchange, transcripts kept under the privacy policy."},"weeks":[{"number":1,"title":"A change you got used to","canDo":"Tell a story about a change: set the scene, sequence events and connect them to now.","featuredVocabulary":["face a challenge","get used to + noun or -ing","since then"],"stretchPhrases":["gradually","look back on"],"grammar":{"main":"Use the past simple for finished events (''I moved last year''), the past continuous for background (''while I was walking home'') and the past perfect for an earlier event (''I''d never run with a group before''). Use the present perfect for a change up to now (''Since then, I''ve made a few friends'').","light":"used to + infinitive for past habits and states; would + infinitive for repeated past actions only (''We would cook together on Sundays'', not ''I would live in Leeds''). Present perfect continuous for an activity continuing up to now (''I''ve been running with the group for six months'').","sampleItems":[{"prompt":"I ___ here last year. Since then, I''ve made a few friends.","options":["moved","have moved"],"key":"moved","reason":"''Last year'' is finished time."},{"prompt":"When I was a child, we ___ in a small flat.","options":["used to live","would live"],"key":"used to live","reason":"''Live'' is a state, so would is not possible."}],"authoringNote":"Would for past habits is not normally used in negatives, questions or states; accept used to or the past simple there, and don''t flag the past simple where used to is possible. Contrast result (''I''ve made a few friends'') and activity (''I''ve been running'')."},"speaking":{"prompt":"What was life like before? What changed, what was difficult, what helped, and what is different now? Listen to the model first, then hide it before recording.","model":"When I moved to a new city last year, I didn''t know anyone. In my old town, I used to see my friends every weekend, and we would often cook together on Sunday evenings. So the biggest challenge I faced was meeting people outside work. It took me a few weeks to get used to spending my evenings alone. One evening, while I was walking home, I saw a poster for a running group. I''d never run with a group before, so I was nervous at the first session, but I gradually got to know the other runners. Since then, I''ve made a few friends, and the city feels more like home. I''ve been running with the group for about six months now. When I look back on those first few weeks, I''m really glad I went to that first session.","b2Stretch":"Explain why the change mattered and how you feel about it now, without the cue card."},"writing":{"words":[120,150],"prompt":"Write a personal narrative about a change. Set the scene, use since then or eventually to move the story on, and close with one sentence about how things are now.","delayedRecall":"Tell me about a new routine that felt strange at first. What helped it feel normal?"},"conversation":{"scenario":"Catching up with an old friend.","openingLine":"It''s been ages! What''s changed since I last saw you?","learnerMoves":"Describe one change, what was hard and how life is now; answer one follow-up.","targetLanguage":"Narrative tenses, present perfect vs past simple, used to / would; face a challenge, get used to, since then"},"vocabulary":{"core":[{"target":"adapt","type":"v.","cefr":"B2","use":"B","example":"I had to adapt to living abroad."},{"target":"turning point","type":"n. phr.","cefr":"B2*","use":"B","example":"Moving to Leeds was a turning point in my life."},{"target":"challenge","type":"n.","cefr":"B1","use":"P","example":"I faced several challenges while I was studying abroad."},{"target":"get used to","type":"v. phr.","cefr":"B1","use":"P","example":"It took me a month to get used to living alone."},{"target":"look back on","type":"mw. v.","cefr":"B2*","use":"B","example":"When I look back on my first year abroad, I remember the people I met."},{"target":"regret","type":"v.","cefr":"B1","use":"P","example":"I''ve never regretted leaving my old job."},{"target":"gradually","type":"adv.","cefr":"B2*","use":"B","example":"My English gradually improved while I was living in York."},{"target":"memorable","type":"adj.","cefr":"B2*","use":"B","example":"Travelling alone was a memorable experience."}],"collocations":[{"target":"make a big decision","example":"I made a big decision about my future."},{"target":"take a risk","example":"I took a risk and applied for a job abroad."},{"target":"make a change","example":"I decided to make a change and cycle to work."},{"target":"keep in touch","example":"I''ve kept in touch with my old school friends."},{"target":"make progress","example":"I''ve been making good progress since September."},{"target":"take up","example":"I took up photography after I moved."}],"families":[{"base":"make a big decision","forms":["decision","decisive","indecisive"],"card":"decision is productive on the collocation card; decisive and indecisive recognition only"},{"base":"adapt","forms":["adaptable"],"card":"recognition only"},{"base":"make a change","forms":["unchanged"],"card":"recognition only"}],"optional":[],"newCards":14,"note":"Teach get used to + noun or -ing for B1 production; contrast used to + infinitive on the same card. Keep adapt to as guided B2."},"linkers":[{"target":"eventually","cefr":"B2","function":"time","taughtIn":"writing task","example":"Eventually, I got used to it."},{"target":"since then","cefr":"B1*","function":"time","taughtIn":"writing task","example":"I moved in September. Since then, I''ve made some good friends."}],"checkpoint1":{"mainItems":4,"lightItems":1,"focus":"Finished time, past-to-now, past continuous background, past perfect sequence; Light: used to / would"}},{"number":2,"title":"A goal and the next step","canDo":"Describe an intention, name an arrangement, say what happens next and what you''ll do if plans change.","featuredVocabulary":["goal","intend to","career","look forward to + noun or -ing"],"stretchPhrases":[],"grammar":{"main":"going to for an intention; present continuous for a confirmed arrangement; will for a prediction or a decision made while speaking; present simple for timetables and ordinary future time clauses (''I''ll apply when I finish''). An indirect question is different: ''I don''t know when I''ll finish''.","light":"Conditionals 0–2 review. Zero for general truth, first for a real possibility, second for an unlikely or imagined situation.","sampleItems":[{"prompt":"I''ll apply as soon as I ___ the course.","options":["finish","will finish"],"key":"finish","reason":"''As soon as'' is a grammar cue here, not a vocabulary target."},{"prompt":"I can''t leave my job, but if I ___ more free time, I''d study full-time.","options":["have","had"],"key":"had","reason":"The situation is imagined."}],"authoringNote":"''I will see my dentist tomorrow'' is grammatical; don''t flag it just because the visit is booked. Accept will or going to for predictions with present evidence. Conditional labels are teaching aids: accept natural variants such as ''when'' in a zero conditional."},"speaking":{"prompt":"Share one goal, one step already arranged, what you''ll do when that step is complete, and what you''ll do if the plan changes.","model":"My goal is to start a career in design. I intend to take a short course this spring, and I''m meeting someone from the college on Thursday. I''m looking forward to seeing some of the students'' work. A friend who did the course has offered to help me choose a project. I think it''ll be hard work, but it''ll be worth it. When I finish the course, I''ll apply for a few junior roles and use my project to show what I can do. If I don''t get a place this spring, I''ll take an evening class instead. And if I had more free time, I''d study full-time, but I need to keep working for now.","b2Stretch":"Explain why the goal matters and weigh two alternatives, without the cue card."},"writing":{"words":[120,150],"prompt":"Write a message to a friend about a goal, a confirmed arrangement, your next step and a back-up plan. Use in order to once to explain a purpose.","delayedRecall":"You''ve decided to learn a new skill. What have you arranged, what will you do afterwards, and what will you do if it doesn''t work out?"},"conversation":{"scenario":"A colleague asks about plans.","openingLine":"So, any plans for the next few months?","learnerMoves":"Give a goal, an arrangement and a next step; say what they''ll do if it doesn''t work out.","targetLanguage":"Future forms, first and second conditionals; goal, intend to, career, look forward to"},"vocabulary":{"core":[{"target":"ambition","type":"n.","cefr":"B1","use":"P","example":"Her ambition is to run her own restaurant."},{"target":"goal","type":"n.","cefr":"B1","use":"P","example":"My goal is to start a career in design."},{"target":"achieve","type":"v.","cefr":"B1","use":"P","example":"If you practise regularly, you''ll achieve your goal."},{"target":"intend","type":"v.","cefr":"B1","use":"P","example":"We intend to move to the coast next year."},{"target":"career","type":"n.","cefr":"B1","use":"P","example":"She''s going to start a career in engineering."},{"target":"deadline","type":"n.","cefr":"B2","use":"B","example":"The deadline for applications is 30 April."},{"target":"apply","type":"v.","cefr":"B1","use":"P","example":"She''s going to apply for a job at the museum."},{"target":"look forward to","type":"mw. v.","cefr":"B1","use":"P","example":"I''m looking forward to starting my new course."},{"target":"determined","type":"adj.","cefr":"B1","use":"B","example":"He''s determined to pass, so he''s going to practise every day."}],"collocations":[{"target":"work towards","example":"I''m working towards a degree in nursing."},{"target":"take the first step","example":"I''ll take the first step and contact the college."},{"target":"improve your skills","example":"This course will help you improve your skills."},{"target":"put (something) off","example":"Don''t put off booking the course. With a pronoun: put it off."},{"target":"set a goal","example":"I''m going to set myself a goal of reading one book a month."},{"target":"meet a deadline","example":"We''ll need to finish on Thursday to meet Friday''s deadline."}],"families":[{"base":"ambition","forms":["ambitious"],"card":"ambitious on ambition; achievable recognition on achieve"},{"base":"achieve","forms":["achievement","achievable"],"card":"achievement on achieve; achievable recognition only"},{"base":"success","forms":["succeed","success","successful","successfully"],"card":"one shared family card; successfully guided B2"}],"optional":[],"newCards":16,"note":"Separate apply for a job from apply to an organisation. In look forward to, to is a preposition: use a noun or an -ing form. No future continuous (Week 14)."},"linkers":[{"target":"in order to","cefr":"B1","function":"purpose","taughtIn":"writing task","example":"In order to save money, I''ll cook at home."}],"checkpoint1":{"mainItems":4,"lightItems":1,"focus":"Intention, arrangement, two ordinary future time clauses; Light: first vs second conditional"}},{"number":3,"title":"Agree on house rules","canDo":"Say what is required, forbidden, optional or possible, ask and give permission, and offer advice.","featuredVocabulary":["get on with","arrange","routine","politely"],"stretchPhrases":[],"grammar":{"main":"have to for a requirement, mustn''t for something forbidden, don''t have to for optional; should for advice; can/can''t now and could/couldn''t for general past ability; ''Can/Could I...?'' to ask permission and ''Yes, you can'' / ''Sorry, you can''t'' to answer.","light":"Question forms: auxiliary before subject (''What time do you usually get home?''), no do in subject questions (''Who takes the bins out?''), statement word order after ''Could you tell me...?''. Basic linkers: on the other hand, in fact, apart from that.","sampleItems":[{"prompt":"Taking turns cooking is optional. You ___ cook on Mondays.","options":["mustn''t","don''t have to"],"key":"don''t have to","reason":"Cooking is allowed, not required."},{"prompt":"___ the bins out on Thursdays?","options":["Who takes","Who does take"],"key":"Who takes","reason":"Who is the subject."}],"authoringNote":"For a specific past success use was able to or managed to, not could; couldn''t works for a specific failure. Keep this contrast as a B2 note, not a scored item."},"speaking":{"prompt":"Welcome a new flatmate who arrives tomorrow: explain one shared responsibility, one rule and one optional routine, give one piece of advice, and end with a question for them. The live flatmate exchange is the conversation task.","model":"Welcome to the flat! There are a few things you need to know. We have to clean up after cooking, and we mustn''t leave the cooker on when we go out. You don''t have to cook for everyone, but we usually eat together on Fridays. You can use the washing machine until ten. The neighbours can hear it through the wall, so if you need it later, please ask them politely first. I couldn''t cook at all when I moved in, so don''t worry if you''re still learning. I think we should arrange a cleaning rota around our work hours. Apart from that, there''s no fixed routine. We all get on with each other really well, so if you''re not sure about something, just ask. What time do you usually get home, by the way?","b2Stretch":"Add a likely problem (noise, guests, bills) and suggest a compromise, without the cue card."},"writing":{"words":[120,150],"prompt":"Write a welcome message for a new flatmate: one requirement, one rule, one optional thing and one piece of advice. Use at least one of the week''s linkers (on the other hand, in fact, apart from that).","delayedRecall":"Tell a new colleague one thing they need to do, one thing they mustn''t do and one thing that''s optional."},"conversation":{"scenario":"A new flatmate''s first evening.","openingLine":"Hi! Is there anything I need to know about the kitchen?","learnerMoves":"Explain a rule, answer a permission request (''Could I use the washing machine tonight?''), ask one question, suggest an arrangement.","targetLanguage":"Obligation, ability and permission modals, question forms, linkers; get on with, arrange, routine, politely"},"vocabulary":{"core":[{"target":"get on with","type":"mw. v.","cefr":"B1","use":"P","example":"You don''t have to be close friends to get on with your colleagues."},{"target":"catch up (with)","type":"phr. v.","cefr":"B2","use":"B","example":"Can we meet after work and catch up? Here: exchange news."},{"target":"arrange","type":"v.","cefr":"B1","use":"P","example":"We should arrange to meet outside the station."},{"target":"routine","type":"n.","cefr":"B1","use":"P","example":"Try to stick to a routine during busy weeks."},{"target":"rely on","type":"mw. v.","cefr":"B2","use":"B","example":"You can rely on Maria to help if there''s a problem."},{"target":"misunderstanding","type":"n.","cefr":"B2","use":"B","example":"We should talk and clear up the misunderstanding."},{"target":"invite (someone) round","type":"phr. v.","cefr":"B1*","use":"P","example":"Can I invite some friends round on Saturday? BrE."},{"target":"awkward (situation)","type":"adj.","cefr":"B2","use":"B","example":"It was an awkward situation, but we managed to talk it through."},{"target":"politely","type":"adv.","cefr":"B1","use":"P","example":"You can disagree politely."}],"collocations":[{"target":"make an effort","example":"We should make an effort to welcome new colleagues."},{"target":"have a lot in common","example":"We have a lot in common: we both love cycling."},{"target":"get in touch","example":"You should get in touch with the organiser."},{"target":"come over","example":"Can you come over for coffee on Saturday?"},{"target":"keep a promise","example":"You should keep a promise even if it''s difficult."}],"families":[{"base":"friend","forms":["unfriendly","friendship"],"card":"shared family card"},{"base":"politely","forms":["politeness","impolite"],"card":"recognition only on politely"},{"base":"rely on","forms":["reliable","unreliable","reliably"],"card":"reliable and unreliable on rely on; reliably recognition only"}],"optional":[{"target":"pop round","example":"Can I pop round after work? Informal BrE; short visit."}],"newCards":15,"note":"Pair get on with (relationship), catch up with (exchange news) and get in touch with (initiate contact). Week 3 linkers are the Light grammar point and required in the welcome-message writing task."},"linkers":[{"target":"on the other hand","cefr":"B1","function":"contrast","taughtIn":"grammar task","example":"Living with friends can be fun. On the other hand, you have to share the housework."},{"target":"in fact","cefr":"B1","function":"emphasis","taughtIn":"grammar task","example":"We get on really well. In fact, we talk almost every day."},{"target":"apart from that","cefr":"B1*","function":"exception","taughtIn":"grammar task","example":"The bus was late. Apart from that, the day went well."}],"checkpoint1":{"mainItems":4,"lightItems":1,"focus":"One item each for obligation, advice, ability and permission; Light: one question form"}},{"number":4,"title":"Give a short visitor guide","canDo":"Describe customs and past facts with the passive, identify places and compare them.","featuredVocabulary":["local","custom","destination","tradition","set off"],"stretchPhrases":[],"grammar":{"main":"be + past participle in present and past simple. Use the passive to focus on the place, event or result; add by + agent only if it matters. Contrast ''is held'' with ''was built'', and keep ''It happened'' active.","light":"Defining relative clauses with who, which, that and where; comparatives and superlatives including irregular better/best and worse/worst. Non-defining clauses are recognition only for now.","sampleItems":[{"prompt":"The craft market ___ in the main square every Sunday.","options":["is held","was held","is hold"],"key":"is held","reason":"Present passive for a regular event."},{"prompt":"It''s ___ market in the region.","options":["the biggest","the bigger","the most big"],"key":"the biggest","reason":"Superlative with the."}],"authoringNote":"Use a guide-card cue such as ''Market hall / build / 1890'' in controlled practice. In free speech accept natural active wording; don''t require a set number of passives."},"speaking":{"prompt":"Record a 60–90 second guide for a first-time visitor. Include a regular event or custom, one fact about the past, one comparison and a recommendation. Don''t require a set number of passives.","model":"If you visit this town, start at the market hall. It was built in 1890, and the food market is held there every Saturday. It''s a local tradition, and you can try food from nearby farms. It''s the busiest place in town on a Saturday morning, so I''d set off early. There''s also a local custom that surprises visitors: most shops are closed on Wednesday afternoons, so plan your shopping for another day. Afterwards, take a walk by the river. It''s quieter than the centre, and it''s the spot where I go to relax. The town isn''t a famous destination, but it''s one of the friendliest places I know.","b2Stretch":"Add extra information with a non-defining clause, such as ''The market hall, which was built in 1890, ...''. Accept it, but don''t require it."},"writing":{"words":[120,150],"prompt":"Write a visitor recommendation or trip note. Separate a place fact from what you personally did, and organise it with to begin with and all in all.","delayedRecall":"Introduce a venue in your neighbourhood. Say what normally takes place there, give one fact about its past and compare it with another place."},"conversation":{"scenario":"A weekend visitor asks for tips.","openingLine":"I''m here for the weekend. What should I see?","learnerMoves":"Recommend a place, give one fact about its past, compare it with another place, mention a custom.","targetLanguage":"Passive, defining relative clauses, comparatives and superlatives; local, custom, destination, tradition, set off"},"vocabulary":{"core":[{"target":"tradition","type":"n.","cefr":"B2","use":"B","example":"Visitors are invited to take part in a local tradition."},{"target":"custom","type":"n.","cefr":"B1","use":"P","example":"The guide explained a local custom: visitors are asked to take off their shoes before they go inside."},{"target":"destination","type":"n.","cefr":"B1","use":"P","example":"It''s one of the most popular holiday destinations on the coast."},{"target":"set off","type":"phr. v.","cefr":"B2","use":"B","example":"We set off early to avoid the heavy traffic."},{"target":"get around","type":"phr. v.","cefr":"B1*","use":"P","example":"We were given a map to help us get around the city."},{"target":"unfamiliar","type":"adj.","cefr":"B2","use":"B","example":"We were unfamiliar with the ticket system."},{"target":"welcoming","type":"adj.","cefr":"B2*","use":"B","example":"The hotel where we stayed had a welcoming atmosphere."},{"target":"local","type":"adj.","cefr":"B1","use":"P","example":"Local food is served in the hotel restaurant."}],"collocations":[{"target":"take a guided tour","example":"We took a guided tour of the old town."},{"target":"try the local food","example":"We were encouraged to try the local food."},{"target":"travel light","example":"We travelled light because there wasn''t much room for luggage."},{"target":"stop overnight","example":"We stopped overnight in York before driving on."},{"target":"miss a connection","example":"Our flight was delayed, so we missed our connection."}],"families":[{"base":"culture","forms":["culture","cultural","culturally"],"card":"one productive family card; culturally recognition only"},{"base":"tradition","forms":["traditional","traditionally"],"card":"on tradition"},{"base":"tourism","forms":["tourism","touristy"],"card":"recognition only"}],"optional":[{"target":"break your journey","example":"We broke our journey with an overnight stay in York. Mainly BrE."}],"newCards":14,"note":"Keep passive models in present and past simple. Destination models a superlative and welcoming a defining relative clause. Local means ''from the area''; touristy is often disapproving."},"linkers":[{"target":"to begin with","cefr":"B1","function":"sequence","taughtIn":"writing task","example":"To begin with, we were shown around the old town."},{"target":"what''s more","cefr":"B2","function":"addition","taughtIn":"writing task","example":"The hotel was comfortable. What''s more, breakfast was included."},{"target":"despite","cefr":"B1","function":"concession","taughtIn":"writing task","example":"Despite the rain, the outdoor tour went ahead."},{"target":"all in all","cefr":"B2*","function":"summary","taughtIn":"writing task","example":"All in all, we had an excellent trip."}],"checkpoint1":{"mainItems":4,"lightItems":1,"focus":"Two present passives and two past passives; Light: one relative clause or comparative/superlative"}}]}'::jsonb->'weeks') week(value)
on conflict (week_number) do update set payload = excluded.payload;

insert into public.syllabus_assessments (code, title, payload) values
  ('writing-descriptors', 'Writing descriptors', '{"version":"2026-11-21","note":"Cut scores and thresholds are provisional until the pilot calibrates them.","writingDescriptors":{"intro":"Writing is marked on the same four criteria as speaking, with B1 as the target for weeks 1–4. Learners see ''Getting there'', ''On target'' or ''Beyond target'' for each criterion, never a number.","criteria":[{"key":"task_achievement","label":"Task achievement","gettingThere":"Misses one or more required points, or under 100 words; the reader would be unsure of the purpose.","onTarget":"Covers every required point in 120–150 words; the text suits its reader (a friend, a flatmate, a visitor).","beyondTarget":"Develops every point with detail, reasons or examples, with a clear sense of the reader."},{"key":"vocabulary","label":"Vocabulary","gettingThere":"Basic, repeated words; errors with common words sometimes block meaning.","onTarget":"Enough everyday vocabulary for the topic; at least two of the week''s featured items used correctly; spelling mostly correct.","beyondTarget":"A wider range, accurate collocations, few spelling errors, and paraphrase where a word is missing."},{"key":"grammar","label":"Grammar","gettingThere":"Frequent errors in the week''s main form; some sentences are hard to follow.","onTarget":"The week''s main form used correctly at least once; simple sentences mostly accurate; errors do not block meaning.","beyondTarget":"Main and light forms used accurately; some longer sentences (relative clauses, time clauses, linkers)."},{"key":"organisation","label":"Organisation","gettingThere":"No clear order or paragraphs; few or no linkers.","onTarget":"A clear beginning, middle and end; paragraphs or clear sections; basic linkers, including the week''s linkers.","beyondTarget":"Well-built paragraphs, varied linkers, and a clear opening and closing."}],"rules":["Length. Under 100 words caps task achievement at ''Getting there''. Over 180 words is not penalised, but feedback suggests cutting.","Spelling. British spelling is taught; American spelling is noted once but not marked as an error.","Honesty. Pasted text, or a sudden jump well above the learner''s usual writing, is flagged for teacher review where a teacher is involved. Checkpoint writing has pasting disabled.","Spanish-speaker errors. Typical Spanish-speaker errors (missing subjects, false friends) are corrected like any other error and logged, so later Spanish-specific notes can draw on them."],"learnerFeedback":"A band for each criterion; one strength quoting the learner''s words; up to two corrections, prioritising the week''s grammar, each with the corrected sentence; then revise-and-retry with a word-by-word comparison of the two drafts.","wordRanges":[{"weeks":"1-4","range":"120–150 words","targetBand":"B1"},{"weeks":"5-8","range":"150–180 words","targetBand":"B1"},{"weeks":"9-12","range":"180–200 words","targetBand":"B1+"},{"weeks":"13-16","range":"200–220 words","targetBand":"B1+"},{"weeks":"Stage 2","range":"220–260 words","targetBand":"B2"}]},"placement":{"durationMinutes":35,"intro":"Placement takes about 35 minutes at sign-up and sends each learner to the foundation course, Stage 1 or Stage 2. The EF SET starting test is taken alongside it as the progress baseline, but placement makes the decision.","parts":[{"part":"Placement test","time":"15 min","what":"24 questions: 10 grammar, 6 vocabulary, 4 reading (one short text), 4 listening (two short clips)","markedBy":"App"},{"part":"Speaking sample","time":"3 min","what":"''Tell me about your job or studies, and what you''d like to be doing in two years'' time.'' 60 seconds, 30 seconds to plan.","markedBy":"AI, on the placement scale"},{"part":"Writing sample","time":"15 min","what":"''Write 80–100 words about a recent trip or event: what happened and what you enjoyed most.''","markedBy":"AI, on the placement scale"}],"questionBlueprint":[{"level":"A2","questions":6,"focus":"Past simple, comparatives, can / have to, everyday vocabulary"},{"level":"B1","questions":8,"focus":"Present perfect vs past simple, future forms, first conditional, modals, B1 vocabulary"},{"level":"B1+","questions":6,"focus":"Past perfect, passive, second conditional, relative clauses, collocations"},{"level":"B2","questions":4,"focus":"Reported speech, third conditional, modals of deduction, B2 vocabulary"}],"bands":[{"band":"A2","description":"''Getting there'' on most criteria: short, simple sentences; frequent errors that sometimes block meaning."},{"band":"B1","description":"''On target'' on most criteria: the task is done clearly; errors do not block meaning."},{"band":"B1+","description":"''Beyond target'' on most criteria: some range and longer, linked sentences."},{"band":"B2","description":"''Beyond target'' on all criteria: wide range, accurate complex sentences, well organised."}],"decisionRules":[{"outcome":"Foundation course","testScore":"0–11","samples":"Or both samples at A2, whatever the test score."},{"outcome":"Stage 1","testScore":"12–18","samples":"At least one sample at B1 or above."},{"outcome":"Stage 2","testScore":"19–24","samples":"Both samples at B1+ or above."}],"borderline":"If the score is within one point of a boundary, or the test and samples point to different results, place the learner in the lower option and tell them they can take a short move-up check after week 2. Where a teacher is involved, they review borderline cases first.","learnerChoice":"A learner placed in Stage 2 may choose to start at Stage 1. A learner placed in the foundation course is shown why, with links to suitable A2 material.","efSetCrossCheck":"If the EF SET result differs from the placement by a full CEFR level or more, the placement is flagged for review; it is not changed automatically."},"checkpoint1":{"intro":"A course checkpoint, not a CEFR placement or certification test. It assesses B1 grammar, a short spoken narrative and a 150-word piece, and is reported beside the learner''s EF SET starting test.","quiz":{"scoredItems":20,"reserveItems":4,"blueprint":"Four Main items and one Light item per week, written separately from the practice item bank so the checkpoint tests learning, not memory of practice items. Order: weeks 1–4, Main then Light. Exclude stretch tasks.","delivery":"Each item is auto-marked; the reason is shown only after the whole checkpoint is submitted. Short scenarios and answer keys allow valid variants; if two options are grammatical, ask which better expresses the stated meaning or accept both.","reporting":"Report results by skill and recommend a specific practice item."},"items":[{"id":"CP1-01","week":1,"target":"Main: finished time","prompt":"We ___ the Colosseum when we were in Rome in 2019.","options":["visited","have visited"],"key":"visited","reason":"''In 2019'' is a finished time."},{"id":"CP1-02","week":1,"target":"Main: past to now","prompt":"My brother ___ three different jobs since he left university.","options":["had","has had"],"key":"has had","reason":"''Since he left'' connects the past to now."},{"id":"CP1-03","week":1,"target":"Main: background","prompt":"The sun ___ (shine) when we left the hotel.","options":[],"key":"was shining","reason":"Background to the main event."},{"id":"CP1-04","week":1,"target":"Main: sequence","prompt":"When I opened the fridge, I realised someone ___ (eat) my cake.","options":[],"key":"had eaten","reason":"It happened before I opened the fridge."},{"id":"CP1-05","week":1,"target":"Light","prompt":"As a teenager, I ___ have very long hair.","options":["used to","would"],"key":"used to","reason":"''Have'' (possession) is a state, so would is not possible."},{"id":"CP1-06","week":2,"target":"Main: intention","prompt":"A: Any plans for the summer? B: I ___ visit my cousins in Ireland, but I haven''t booked anything yet.","options":["''m going to","''m visiting"],"key":"''m going to","reason":"An intention with nothing arranged yet."},{"id":"CP1-07","week":2,"target":"Main: arrangement","prompt":"We ___ (fly) to Lisbon on Friday. The tickets are in my bag.","options":[],"key":"''re flying (are flying)","reason":"A fixed arrangement."},{"id":"CP1-08","week":2,"target":"Main: time clause","prompt":"I''ll send you the photos when I ___ home.","options":["get","''ll get"],"key":"get","reason":"After ''when'', use the present simple for the future."},{"id":"CP1-09","week":2,"target":"Main: time clause","prompt":"As soon as the film ___ (finish), we''ll go for dinner.","options":[],"key":"finishes","reason":"After ''as soon as'', use the present simple for the future."},{"id":"CP1-10","week":2,"target":"Light","prompt":"If I ___ the lottery, I''d buy a house by the sea.","options":["won","win"],"key":"won","reason":"Second conditional: an imagined situation."},{"id":"CP1-11","week":3,"target":"Main: obligation","prompt":"In the UK, you ___ drive on the left.","options":["have to","don''t have to"],"key":"have to","reason":"It is a rule."},{"id":"CP1-12","week":3,"target":"Main: advice","prompt":"If you want to improve your English, you ___ read a little every day.","options":["should","mustn''t"],"key":"should","reason":"Advice."},{"id":"CP1-13","week":3,"target":"Main: ability","prompt":"My grandmother ___ (can / not / use) a smartphone, so we phone her.","options":[],"key":"can''t use (cannot use)","reason":"Ability, negative."},{"id":"CP1-14","week":3,"target":"Main: permission","prompt":"___ I leave my bag here while I go to the toilet?","options":["Can","Must"],"key":"Can (Could)","reason":"Asking for permission."},{"id":"CP1-15","week":3,"target":"Light","prompt":"Put the words in order: Where / you / do / work?","options":[],"key":"Where do you work?","reason":"Auxiliary before the subject."},{"id":"CP1-16","week":4,"target":"Main: present passive","prompt":"Cheese ___ (make) from milk.","options":[],"key":"is made","reason":"A general fact; the cheese is the focus."},{"id":"CP1-17","week":4,"target":"Main: present passive","prompt":"Most of the city''s buses ___ by electricity now.","options":["are powered","power"],"key":"are powered","reason":"Something powers the buses."},{"id":"CP1-18","week":4,"target":"Main: past passive","prompt":"The first email ___ (send) in 1971.","options":[],"key":"was sent","reason":"Past passive."},{"id":"CP1-19","week":4,"target":"Main: past passive","prompt":"Our flight ___ because of the snow.","options":["was cancelled","cancelled"],"key":"was cancelled","reason":"The airline cancelled it."},{"id":"CP1-20","week":4,"target":"Light","prompt":"This is the hotel ___ we stayed last summer.","options":["where","who"],"key":"where","reason":"''Where'' for a place followed by a full clause."}],"reserves":[{"id":"CP1-R1","week":1,"target":"reserve","prompt":"I ___ (not / see) her since the wedding.","options":[],"key":"haven''t seen (have not seen)","reason":"Up to now with since."},{"id":"CP1-R2","week":2,"target":"reserve","prompt":"Don''t worry, I ___ (call) you before I ___ (leave).","options":[],"key":"''ll call ... leave","reason":"Will for the promise; present simple after before."},{"id":"CP1-R3","week":3,"target":"reserve","prompt":"You ___ (not / have to) come to the party if you''re tired.","options":[],"key":"don''t have to","reason":"It isn''t necessary."},{"id":"CP1-R4","week":4,"target":"reserve","prompt":"The Alhambra ___ (visit) by millions of people every year.","options":[],"key":"is visited","reason":"Present passive with by."}],"reserveUse":"Reserves replace an item that pilot data shows is unclear, or form a retake for learners repeating the checkpoint.","speakingTask":"A recorded 60–90 second narrative in response to a new prompt about a change, from the weeks 1–4 speaking content.","writing":{"prompts":[{"label":"A. A change I got used to","text":"Describe how life was before a change, what happened, what was difficult, and how things are now."},{"label":"B. A note for a visitor","text":"A friend is visiting your town for a weekend. Recommend what to see: include a regular event or custom, one fact about a place''s past, a comparison, and one piece of advice."}],"conditions":[{"id":"length","setting":"Length","value":"150 words (130–170 accepted)"},{"id":"time","setting":"Time","value":"30 minutes, with a visible timer"},{"id":"where","setting":"Where","value":"In the app; pasting disabled; no phrase bank or model"},{"id":"attempts","setting":"Attempts","value":"One submission; no revise-and-retry"},{"id":"marking","setting":"Marking","value":"AI bands on the four writing criteria straight away; a teacher confirms where one is involved, and the teacher''s mark counts"}]},"result":{"intro":"Results are reported by part and by week, never as pass or fail. Learners continue to week 5 whatever their result; the checkpoint guides practice, it does not block progress.","thresholds":[{"part":"Quiz","onTarget":"14 of 20 or more (70%)"},{"part":"Speaking","onTarget":"''On target'' or better on at least three criteria, and task achievement not at ''Getting there''"},{"part":"Writing","onTarget":"''On target'' or better on at least three criteria, and task achievement not at ''Getting there''"}],"practiceLinks":"Each part below target links to the matching practice: weak quiz items to that week''s extra items and grammar clinic, speaking to the week''s shadowing and conversation, writing to a revise-and-retry task on the same prompt."},"calibration":["A second teacher checks every checkpoint item for a single correct answer and accepted variants.","Check the existing 24 placement questions against the blueprint (6 A2, 8 B1, 6 B1+, 4 B2) and replace those that do not fit.","Mark 10–20 sample texts and recordings by hand and compare with the AI''s bands; adjust prompts until they agree on at least 8 in 10.","After 30 placed learners, compare placement with EF SET results and adjust the cut scores (11/12 and 18/19).","Review any checkpoint item that more than 90% or fewer than 30% of pilot learners answer correctly.","Confirm the checkpoint thresholds (70% quiz, three of four criteria) against teacher judgement of pilot learners."]}}'::jsonb->'writingDescriptors'),
