from jsonb_to_recordset('[{"id":"CP1-01","week_number":1,"reserve":false,"target":"Main: finished time","prompt":"We ___ the Colosseum when we were in Rome in 2019.","options":["visited","have visited"],"key":"visited","reason":"''In 2019'' is a finished time.","sort_order":1},{"id":"CP1-02","week_number":1,"reserve":false,"target":"Main: past to now","prompt":"My brother ___ three different jobs since he left university.","options":["had","has had"],"key":"has had","reason":"''Since he left'' connects the past to now.","sort_order":2},{"id":"CP1-03","week_number":1,"reserve":false,"target":"Main: background","prompt":"The sun ___ (shine) when we left the hotel.","options":[],"key":"was shining","reason":"Background to the main event.","sort_order":3},{"id":"CP1-04","week_number":1,"reserve":false,"target":"Main: sequence","prompt":"When I opened the fridge, I realised someone ___ (eat) my cake.","options":[],"key":"had eaten","reason":"It happened before I opened the fridge.","sort_order":4},{"id":"CP1-05","week_number":1,"reserve":false,"target":"Light","prompt":"As a teenager, I ___ have very long hair.","options":["used to","would"],"key":"used to","reason":"''Have'' (possession) is a state, so would is not possible.","sort_order":5},{"id":"CP1-06","week_number":2,"reserve":false,"target":"Main: intention","prompt":"A: Any plans for the summer? B: I ___ visit my cousins in Ireland, but I haven''t booked anything yet.","options":["''m going to","''m visiting"],"key":"''m going to","reason":"An intention with nothing arranged yet.","sort_order":6},{"id":"CP1-07","week_number":2,"reserve":false,"target":"Main: arrangement","prompt":"We ___ (fly) to Lisbon on Friday. The tickets are in my bag.","options":[],"key":"''re flying (are flying)","reason":"A fixed arrangement.","sort_order":7},{"id":"CP1-08","week_number":2,"reserve":false,"target":"Main: time clause","prompt":"I''ll send you the photos when I ___ home.","options":["get","''ll get"],"key":"get","reason":"After ''when'', use the present simple for the future.","sort_order":8},{"id":"CP1-09","week_number":2,"reserve":false,"target":"Main: time clause","prompt":"As soon as the film ___ (finish), we''ll go for dinner.","options":[],"key":"finishes","reason":"After ''as soon as'', use the present simple for the future.","sort_order":9},{"id":"CP1-10","week_number":2,"reserve":false,"target":"Light","prompt":"If I ___ the lottery, I''d buy a house by the sea.","options":["won","win"],"key":"won","reason":"Second conditional: an imagined situation.","sort_order":10},{"id":"CP1-11","week_number":3,"reserve":false,"target":"Main: obligation","prompt":"In the UK, you ___ drive on the left.","options":["have to","don''t have to"],"key":"have to","reason":"It is a rule.","sort_order":11},{"id":"CP1-12","week_number":3,"reserve":false,"target":"Main: advice","prompt":"If you want to improve your English, you ___ read a little every day.","options":["should","mustn''t"],"key":"should","reason":"Advice.","sort_order":12},{"id":"CP1-13","week_number":3,"reserve":false,"target":"Main: ability","prompt":"My grandmother ___ (can / not / use) a smartphone, so we phone her.","options":[],"key":"can''t use (cannot use)","reason":"Ability, negative.","sort_order":13},{"id":"CP1-14","week_number":3,"reserve":false,"target":"Main: permission","prompt":"___ I leave my bag here while I go to the toilet?","options":["Can","Must"],"key":"Can (Could)","reason":"Asking for permission.","sort_order":14},{"id":"CP1-15","week_number":3,"reserve":false,"target":"Light","prompt":"Put the words in order: Where / you / do / work?","options":[],"key":"Where do you work?","reason":"Auxiliary before the subject.","sort_order":15},{"id":"CP1-16","week_number":4,"reserve":false,"target":"Main: present passive","prompt":"Cheese ___ (make) from milk.","options":[],"key":"is made","reason":"A general fact; the cheese is the focus.","sort_order":16},{"id":"CP1-17","week_number":4,"reserve":false,"target":"Main: present passive","prompt":"Most of the city''s buses ___ by electricity now.","options":["are powered","power"],"key":"are powered","reason":"Something powers the buses.","sort_order":17},{"id":"CP1-18","week_number":4,"reserve":false,"target":"Main: past passive","prompt":"The first email ___ (send) in 1971.","options":[],"key":"was sent","reason":"Past passive.","sort_order":18},{"id":"CP1-19","week_number":4,"reserve":false,"target":"Main: past passive","prompt":"Our flight ___ because of the snow.","options":["was cancelled","cancelled"],"key":"was cancelled","reason":"The airline cancelled it.","sort_order":19},{"id":"CP1-20","week_number":4,"reserve":false,"target":"Light","prompt":"This is the hotel ___ we stayed last summer.","options":["where","who"],"key":"where","reason":"''Where'' for a place followed by a full clause.","sort_order":20},{"id":"CP1-R1","week_number":1,"reserve":true,"target":"reserve","prompt":"I ___ (not / see) her since the wedding.","options":[],"key":"haven''t seen (have not seen)","reason":"Up to now with since.","sort_order":1},{"id":"CP1-R2","week_number":2,"reserve":true,"target":"reserve","prompt":"Don''t worry, I ___ (call) you before I ___ (leave).","options":[],"key":"''ll call ... leave","reason":"Will for the promise; present simple after before.","sort_order":2},{"id":"CP1-R3","week_number":3,"reserve":true,"target":"reserve","prompt":"You ___ (not / have to) come to the party if you''re tired.","options":[],"key":"don''t have to","reason":"It isn''t necessary.","sort_order":3},{"id":"CP1-R4","week_number":4,"reserve":true,"target":"reserve","prompt":"The Alhambra ___ (visit) by millions of people every year.","options":[],"key":"is visited","reason":"Present passive with by.","sort_order":4}]'::jsonb) as v(
  id text, week_number int, reserve boolean, target text, prompt text, options jsonb,
  key text, reason text, sort_order int
)
on conflict (id) do update set week_number = excluded.week_number, reserve = excluded.reserve,
